export function makeMessage(displayName) {
  if (typeof displayName !== 'string') throw new TypeError('string required');
  return { displayName };
}
export function encodeMessage(value) {
  return JSON.stringify({ displayName: value.displayName });
}
export function decodeMessage(line) {
  const value = JSON.parse(line);
  return makeMessage(Object.hasOwn(value, 'displayName') ? value.displayName : value.caption);
}

